import io
import json
import openai_client

class Response:
    def __enter__(self): return self
    def __exit__(self, *args): pass
    def read(self):
        return json.dumps({\"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"ok\"}]}]}).encode()

class Opener:
    def open(self, request, timeout):
        assert request.full_url == \"https://api.openai.com/v1/responses\"
        assert json.loads(request.data) == {\"model\": \"test-model\", \"input\": \"private\"}
        assert timeout == 60.0
        return Response()

client = openai_client.OpenAIClient(\"test-key\")
client._opener = Opener()
assert client.ask(\"private\", model=\"test-model\") == \"ok\"
print(\"compile and mock request test passed\")
