/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import urllib.error
import openai_client

secret = \"PRIVATE_SENTINEL\"
client = openai_client.OpenAIClient(\"key\")
class Broken:
    def open(self, *args, **kwargs):
        raise urllib.error.URLError(secret)
client._opener = Broken()
try:
    client.ask(secret, model=\"test\")
except openai_client.OpenAIConnectionError as exc:
    assert secret not in str(exc)
else:
    raise AssertionError(\"expected connection error\")

for value in (\"x\\ny\", \"x\\ry\"):
    try:
        openai_client.OpenAIClient(\"key\", organization=value)
    except ValueError:
        pass
    else:
        raise AssertionError(\"header injection accepted\")
print(\"privacy and validation tests passed\")
PY"

